  return {
    state: game,
    lastUpkeep,
    lastRemoved,
    addCard,
    removeCard,
    undoRemove,
    dismissLastRemoved,
    setCount,
    adjustCount,
    setTurn,
    nextTurn,
    applyTimeTravel,
    dismissUpkeep,
    castCommander,
    returnCommanderToCommandZone,
    adjustRoseTimeCounters,
    roseAttacks,
    resetGame,
  };
}

