import { render, screen, waitFor } from '@testing-library/react';
import UndoToast from './UndoToast';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

describe('UndoToast', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.runOnlyPendingTimers();
    vi.clearAllTimers();
    vi.restoreAllMocks();
  });

  it('shows the card name and has both buttons', () => {
    const onUndo = vi.fn();
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={onUndo}
        onDismiss={onDismiss}
      />,
    );

    expect(screen.getByText('Test Spell removed')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Undo/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Dismiss/i })).toBeInTheDocument();
  });

  it('onDismiss fires once after 6000 ms and not before', () => {
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });

  it('a second removal with same cardName but different instanceId gets its own full 6000 ms', async () => {
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="first-copy-1"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="second-copy-2"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    await waitFor(() => expect(screen.getByText('Suspended Spell removed')).toBeInTheDocument());
    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="third-copy-3"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    await waitFor(() => expect(screen.getByText('Suspended Spell removed')).toBeInTheDocument());
    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(3);
  });
});

