import { render, screen } from '@testing-library/react';
import UndoToast from './UndoToast';
import { afterEach, vi } from 'vitest';
import { describe, expect, it, beforeEach } from 'vitest';

describe('UndoToast', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.runOnlyPendingTimers();
    vi.clearAllTimers();
    vi.useRealTimers();
  });

  it('shows the card name and has both buttons', () => {
    const onUndo = vi.fn();
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={onUndo}
        onDismiss={onDismiss}
      />,
    );

    expect(screen.getByText('Test Spell removed')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Undo/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Dismiss/i })).toBeInTheDocument();
  });

  it('onDismiss fires once after 6000 ms and not before', () => {
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });

  it('a second removal with same cardName but different instanceId gets its own full 6000 ms', () => {
    let onDismiss: ReturnType<typeof vi.fn>;
    let instanceCount = 0;

    const getInstanceCount = () => {
      instanceCount++;
      return instanceCount;
    };

    const renderToast = (instanceId: string) => {
      onDismiss = vi.fn();
      render(
        <UndoToast
          cardName="Suspended Spell"
          instanceId={instanceId}
          onUndo={vi.fn()}
          onDismiss={onDismiss}
        />,
      );
      return getInstanceCount();
    };

    const renderToastRerender = (instanceId: string, forceClear = false) => {
      if (forceClear || onDismiss === undefined) {
        onDismiss = vi.fn();
      }
      render(
        <UndoToast
          cardName="Suspended Spell"
          instanceId={instanceId}
          onUndo={vi.fn()}
          onDismiss={onDismiss}
        />,
      );
      return onDismiss;
    };

    // First toast - starts 6s timer
    instanceCount = renderToast('first-copy-1');
    expect(onDismiss).not.toHaveBeenCalled();

    // Advance 5s - timer still running
    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    // Re-render same name, different instanceId
