      />,
    );

    expect(screen.getByText('Test Spell removed')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Undo/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Dismiss/i })).toBeInTheDocument();
  });

  it('onDismiss fires once after 6000 ms and not before', () => {
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });

  it('a second removal with same cardName but different instanceId gets its own full 6000 ms', () => {
    // Scenario: Render first toast, wait 5s, render second toast
    // Verify each toast gets its own 6s timer

    const onDismiss1 = vi.fn();
    const onDismiss2 = vi.fn();

    // Render first toast - its timer starts ticking
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="removed-first"
        onUndo={vi.fn()}
        onDismiss={onDismiss1}
      />,
    );

    expect(onDismiss1).not.toHaveBeenCalled();

    // Wait 5 seconds
    vi.advanceTimersByTime(5000);
    expect(onDismiss1).not.toHaveBeenCalled();

    // Render second toast with same cardName but different instanceId
    // Because instanceId in the dependency array changed, useEffect re-runs
    // creating a fresh 6s timer
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="removed-second"
        onUndo={vi.fn()}
        onDismiss={onDismiss2}
      />,
    );

    // At this point, we've advanced 5s total in the test
    // Toast 1's timer has counted 5s (1s left to fire but we'll test it separately)
    // Toast 2's timer is now at 0s (was just created)
    // 
    // The bug would cause Toast 2 to fire immediately, clearing Toast 1's timer
    // and replacing with Toast 2's dismissal

    expect(onDismiss1).not.toHaveBeenCalled();
    expect(onDismiss2).not.toHaveBeenCalled();

    // Advance 1 more second - Toast 1 should fire now
    // Toast 2 has had only 5s of timer (will fire in 1 more second)
    vi.advanceTimersByTime(1000);

    // Toast 1 should fire (6000ms total)
    expect(onDismiss1).toHaveBeenCalledTimes(1);
    // Toast 2 has only 6s now too, so it should fire now as well
    expect(onDismiss2).toHaveBeenCalledTimes(1);

    // Verify: both toasts had their complete 6000ms windows
    expect(onDismiss1).toHaveBeenCalledTimes(1);
    expect(onDismiss2).toHaveBeenCalledTimes(1);
  });
});

