import { render, screen } from '@testing-library/react';
import UndoToast from './UndoToast';
import { describe, expect, it, vi, beforeEach, afterEach } from 'vitest';

describe('UndoToast', () => {
  beforeEach(() => {
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.runOnlyPendingTimers();
    vi.clearAllTimers();
    vi.useRealTimers();
  });

  it('shows the card name and has both buttons', () => {
    const onUndo = vi.fn();
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={onUndo}
        onDismiss={onDismiss}
      />,
    );

    expect(screen.getByText('Test Spell removed')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Undo/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Dismiss/i })).toBeInTheDocument();
  });

  it('onDismiss fires once after 6000 ms and not before', () => {
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });

  it('renders correctly with different instanceIds for same cardName', () => {
    const onDismiss = vi.fn();
    vi.useFakeTimers();

    // Render first toast
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="instance-1"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();
    expect(screen.getByText('Suspended Spell removed')).toBeInTheDocument();
  });

  it('handles same cardName with different instanceIds via Rerender', () => {
    // Track both instance dismissal events
    const onDismiss1 = vi.fn();
    const onDismiss2 = vi.fn();

    // Render first toast
    const { rerender } = render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="removed-first"
        onUndo={vi.fn()}
        onDismiss={onDismiss1}
      />,
    );

    // Wait 5 seconds
    vi.advanceTimersByTime(5000);
    expect(onDismiss1).not.toHaveBeenCalled();

    // Render second toast with same name but different id - should fire timer2
    // (effect re-runs with new instanceId, creating new 6s timer)
    rerender(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="removed-second"
        onUndo={vi.fn()}
        onDismiss={onDismiss2}
      />,
    );

    // At 5s mark, neither has fired
    expect(onDismiss1).not.toHaveBeenCalled();
    expect(onDismiss2).not.toHaveBeenCalled();
    expect(screen.getByText('Suspended Spell removed')).toBeInTheDocument();
  });

  it('each instanceId gets 6000ms', () => {
    // Scenario: each toast should have own 6s window
    const onDismiss1 = vi.fn();
    const onDismiss2 = vi.fn();

    vi.useFakeTimers();

    // Render first toast
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="removed-first"
        onUndo={vi.fn()}
        onDismiss={onDismiss1}
      />,
    );

    // Wait 5 seconds
    vi.advanceTimersByTime(5000);
    expect(onDismiss1).not.toHaveBeenCalled();

    // Render second toast
    render(
      <UndoToast
        cardName="Suspended Spell"
        instanceId="removed-second"
        onUndo={vi.fn()}
        onDismiss={onDismiss2}
      />,
    );

    // Now both have been exposed to simulated time
    // Toast 1 had 5s, then waited 1s = 6s total (fire)
    // Toast 2 had 5s, then 1s = 6s total (fire)
    vi.advanceTimersByTime(1000);

    // Both should fire
    expect(onDismiss1).toHaveBeenCalledTimes(1);
    expect(onDismiss2).toHaveBeenCalledTimes(1);
  });
});

