import { render, screen } from '@testing-library/react';
import UndoToast from './UndoToast';
import { describe, expect, it, vi } from 'vitest';

describe('UndoToast', () => {
  it('shows the card name and has both buttons', () => {
    const onUndo = vi.fn();
    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={onUndo}
        onDismiss={onDismiss}
      />,
    );

    expect(screen.getByText('Test Spell removed')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Undo/i })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: /Dismiss/i })).toBeInTheDocument();
  });

  it('onDismiss fires once after 6000 ms and not before', () => {
    vi.useFakeTimers();

    const onDismiss = vi.fn();

    render(
      <UndoToast
        cardName="Test Spell"
        instanceId="test-123"
        onUndo={vi.fn()}
        onDismiss={onDismiss}
      />,
    );

    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(5000);
    expect(onDismiss).not.toHaveBeenCalled();

    vi.advanceTimersByTime(1000);
    expect(onDismiss).toHaveBeenCalledTimes(1);
  });

  it('handles multiple removals mounted simultaneously with independent 6000 ms timers', () => {
    const onDismiss1 = vi.fn();
    const onDismiss2 = vi.fn();

    vi.useFakeTimers();

    // Render both toasts at once - each starts its own 6000ms timer
    render(
      <>
        <UndoToast
          cardName="Suspended Spell"
          instanceId="removed-first"
          onUndo={vi.fn()}
          onDismiss={onDismiss1}
        />
        <UndoToast
          cardName="Suspended Spell"
          instanceId="removed-second"
          onUndo={vi.fn()}
          onDismiss={onDismiss2}
        />
      </>,
    );

    // Neither should fire immediately
    expect(onDismiss1).not.toHaveBeenCalled();
    expect(onDismiss2).not.toHaveBeenCalled();

    // Advance 5 seconds - neither should fire (need full 6s)
    vi.advanceTimersByTime(5000);
    expect(onDismiss1).not.toHaveBeenCalled();
    expect(onDismiss2).not.toHaveBeenCalled();

    // Advance 1 more second - both should fire (each has accumulated 6s)
    vi.advanceTimersByTime(1000);

    expect(onDismiss1).toHaveBeenCalledTimes(1);
    expect(onDismiss2).toHaveBeenCalledTimes(1);
  });
});
